namespace scratchbird::engine::sblr{namespace{bool nz(const auto&a){return std::any_of(a.begin(),a.end(),[](auto b){return b;});}void p16(auto&o,uint16_t v){o.push_back(v);o.push_back(v>>8);}void p32(auto&o,uint32_t v){for(int i=0;i<4;i++)o.push_back(v>>(8*i));}void p64(auto&o,uint64_t v){for(int i=0;i<8;i++)o.push_back(v>>(8*i));}uint16_t u16(const uint8_t*p){return p[0]|p[1]<<8;}uint32_t u32(const uint8_t*p){uint32_t v=0;for(int i=3;i>=0;i--)v=v*256+p[i];return v;}uint64_t u64(const uint8_t*p){uint64_t v=0;for(int i=7;i>=0;i--)v=v*256+p[i];return v;}void put(auto&o,const auto&a){o.insert(o.end(),a.begin(),a.end());}void get(const uint8_t*p,auto&a){std::copy(p,p+a.size(),a.begin());}bool head(const uint8_t*b,size_t n,const char*m,size_t z){return n==z&&std::equal(m,m+4,b)&&b[4]==1&&!b[5]&&u16(b+6)==z&&u32(b+8)==z&&!u32(b+12);}auto hash(const char*d,const std::vector<uint8_t>&b){std::vector<uint8_t>m(d,d+std::char_traits<char>::length(d));m.insert(m.end(),b.begin(),b.end());return scratchbird::core::hash::ComputeSha256Digest(m).digest;}}
std::vector<uint8_t>EncodeSblrAccessCursorCloseRequestV1(const SblrAccessCursorCloseRequestV1&v){if(!nz(v.receipt)||!v.occurrence||!v.close_occurrence)return{};std::vector<uint8_t>o{'A','C','L','Q'};p16(o,1);p16(o,64);p32(o,64);p32(o,0);put(o,v.receipt);p64(o,v.occurrence);p32(o,v.close_occurrence);o.insert(o.end(),20,0);return o;}bool DecodeSblrAccessCursorCloseRequestV1(const uint8_t*b,size_t n,SblrAccessCursorCloseRequestV1*out,std::string*d){if(!out||!head(b,n,"ACLQ",64)){if(d)*d="ACLQ invalid";return false;}SblrAccessCursorCloseRequestV1 v;get(b+16,v.receipt);v.occurrence=u64(b+32);v.close_occurrence=u32(b+40);if(std::any_of(b+44,b+64,[](auto x){return x;})||EncodeSblrAccessCursorCloseRequestV1(v).empty())return false;*out=v;return true;}
std::vector<uint8_t>EncodeSblrAccessCursorCloseDescriptorV1(const SblrAccessCursorCloseDescriptorV1&v,bool op){if(!nz(v.descriptor)||!v.descriptor_generation||!nz(v.cursor)||!v.cursor_generation||!nz(v.relation)||!nz(v.session)||!nz(v.transaction)||!nz(v.position_token)||!v.position_generation||v.close_reason!=1||v.lifecycle_state!=1||!nz(v.catalog)||!v.availability_generation)return{};std::vector<uint8_t>o=op?std::vector<uint8_t>{'A','C','L','O'}:std::vector<uint8_t>{'A','C','L','D'};p16(o,1);p16(o,232);p32(o,232);p32(o,0);put(o,v.descriptor);p64(o,v.descriptor_generation);put(o,v.cursor);p64(o,v.cursor_generation);put(o,v.relation);put(o,v.index);put(o,v.session);put(o,v.transaction);put(o,v.position_token);p64(o,v.position_generation);o.push_back(v.close_reason);o.push_back(v.lifecycle_state);o.insert(o.end(),6,0);put(o,v.catalog);auto e=hash("ScratchBird.SblrAccessCursorCloseDescriptor.V1",std::vector<uint8_t>(o.begin()+16,o.end()));if(nz(v.evidence)&&v.evidence!=e)return{};put(o,e);p64(o,v.availability_generation);return o;}bool DecodeSblrAccessCursorCloseDescriptorV1(const uint8_t*b,size_t n,SblrAccessCursorCloseDescriptorV1*out,std::string*d,bool op){if(!out||!head(b,n,op?"ACLO":"ACLD",232)){if(d)*d="access cursor close descriptor invalid";return false;}SblrAccessCursorCloseDescriptorV1 v;get(b+16,v.descriptor);v.descriptor_generation=u64(b+32);get(b+40,v.cursor);v.cursor_generation=u64(b+56);get(b+64,v.relation);get(b+80,v.index);get(b+96,v.session);get(b+112,v.transaction);get(b+128,v.position_token);v.position_generation=u64(b+160);v.close_reason=b[168];v.lifecycle_state=b[169];get(b+176,v.catalog);get(b+192,v.evidence);v.availability_generation=u64(b+224);if(std::any_of(b+170,b+176,[](auto x){return x;})||EncodeSblrAccessCursorCloseDescriptorV1(v,op).empty())return false;*out=v;return true;}}
